package com.app.socialservice.user.domain.model.valueobj;

import java.util.Objects;
import java.util.UUID;
import java.util.regex.Pattern;

import com.app.socialservice.user.domain.enums.ProfilePictureContentType;
import com.app.socialservice.user.domain.exception.InvalidProfilePictureException;

/**
 * Name of an avatar blob in the media container: {@code avatars/{userId}/{uuid}.{ext}}. Always
 * generated by the server, never chosen by the client, so a user can only ever write into and
 * point at their own folder.
 */
public record ProfilePictureBlobName(String value) {

    public static final String FOLDER = "avatars";

    private static final Pattern FORMAT = Pattern.compile(
            "^" + FOLDER + "/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/"
                    + "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\.([a-z]+)$");

    public ProfilePictureBlobName {
        if (value == null || !FORMAT.matcher(value).matches()) {
            throw new InvalidProfilePictureException("Profile picture is not an avatar blob: " + value);
        }
        var matcher = FORMAT.matcher(value);
        matcher.matches();
        if (!ProfilePictureContentType.isKnownExtension(matcher.group(2))) {
            throw new InvalidProfilePictureException("Profile picture has an unsupported extension: " + value);
        }
    }

    public static ProfilePictureBlobName generate(UserId owner, ProfilePictureContentType contentType) {
        Objects.requireNonNull(owner, "owner must not be null");
        Objects.requireNonNull(contentType, "contentType must not be null");
        return new ProfilePictureBlobName(String.format(
                "%s/%s/%s.%s", FOLDER, owner.value(), UUID.randomUUID(), contentType.extension()));
    }

    /**
     * Parses a blob name sent back by a client and checks it lies in the caller's own folder.
     */
    public static ProfilePictureBlobName ownedBy(UserId owner, String blobName) {
        Objects.requireNonNull(owner, "owner must not be null");
        var name = new ProfilePictureBlobName(blobName);
        var matcher = FORMAT.matcher(name.value());
        matcher.matches();
        if (!matcher.group(1).equals(owner.value().toString())) {
            throw new InvalidProfilePictureException("Profile picture must be under the caller's avatars folder");
        }
        return name;
    }
}
